import { Effect } from "effect";
import type { TaskFeed } from "./task-feed";

const selectedTenant = "tenant-a";

/** The caller holds this tenant's admission lock through the eventual enqueue. */
export const mayQueueAssetPack = Effect.fnUntraced(function* (feed: TaskFeed) {
  const unfinished = yield* feed.unfinishedForTenant(selectedTenant);
  const duplicates = unfinished.filter((task) => task.kind === "asset-pack");
  return duplicates.length === 0;
});

import { Effect } from "effect";
import type { TaskFeed } from "./task-feed";

const selectedTenant = "tenant-a";

/** The caller holds this tenant's admission lock through the eventual enqueue. */
export const mayQueueAssetPack = Effect.fnUntraced(function* (feed: TaskFeed) {
  const page = yield* feed.newest(10);
  const duplicates = page.filter(
    (task) =>
      task.tenantId === selectedTenant &&
      task.kind === "asset-pack" &&
      (task.state === "waiting" || task.state === "running"),
  );
  return duplicates.length === 0;
});

import { Effect, Schema } from "effect";

export const TenantId = Schema.String.check(
  Schema.isPattern(/^tenant-[a-z]+$/),
);
export type TenantId = typeof TenantId.Type;

export const TaskState = Schema.Literals(["waiting", "running", "done"]);
export type TaskState = typeof TaskState.Type;

export const TaskRecord = Schema.Struct({
  id: Schema.String,
  tenantId: TenantId,
  kind: Schema.Literals(["asset-pack", "thumbnail"]),
  state: TaskState,
  outcome: Schema.NullOr(Schema.Literals(["succeeded", "failed", "canceled"])),
  createdAt: Schema.Number,
});
export type TaskRecord = typeof TaskRecord.Type;

export interface TaskFeed {
  /** Newest createdAt first across all tenants, kinds, and states; returns at most limit rows. */
  readonly newest: (limit: number) => Effect.Effect<ReadonlyArray<TaskRecord>>;
  /** Traverses every cursor page; returns all waiting or running tasks for exactly this tenant. */
  readonly unfinishedForTenant: (tenant: TenantId) => Effect.Effect<ReadonlyArray<TaskRecord>>;
}

